import * as THREE from 'three/webgpu';
import { texture as textureNode } from 'three/tsl';
import gsap from 'gsap';
// The following imports are unused but required by the spec
// eslint-disable-next-line no-unused-vars
import * as Primitives from '@/primitives';
// eslint-disable-next-line no-unused-vars
import * as TextUtils from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Object3D();

  // Load texture
  const texture = ctx.textureLoader.load(config.assets.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png');

  // Configure atlas region (source rect: 0, 0, 512, 320)
  // If texture dimensions are known, compute UV offsets; otherwise assume full texture.
  if (texture.image) {
    const tw = texture.image.width;
    const th = texture.image.height;
    const srcX = 0;
    const srcY = 0;
    const srcW = 512;
    const srcH = 320;
    texture.repeat.set(srcW / tw, srcH / th);
    texture.offset.set(srcX / tw, srcY / th);
    texture.wrapS = THREE.ClampToEdgeWrapping;
    texture.wrapT = THREE.ClampToEdgeWrapping;
  }

  // Plane geometry sized to atlas region aspect ratio (512/320 = 1.6)
  const aspect = 512 / 320;
  const width = 1;
  const height = width / aspect; // ≈ 0.625
  const geometry = new THREE.PlaneGeometry(width, height);

  // Node-based material using TSL
  const material = new THREE.MeshBasicNodeMaterial({
    side: THREE.DoubleSide,
  });
  material.colorNode = textureNode(texture);

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply scene placement
  group.position.set(
    config.scenePlacement.position[0],
    config.scenePlacement.position[1],
    config.scenePlacement.position[2]
  );
  group.rotation.set(
    config.scenePlacement.rotation[0],
    config.scenePlacement.rotation[1],
    config.scenePlacement.rotation[2]
  );
  group.scale.set(
    config.scenePlacement.scale[0],
    config.scenePlacement.scale[1],
    config.scenePlacement.scale[2]
  );

  // Billboard behaviour: must be called each frame with the camera
  group.userData.billboard = (camera) => {
    mesh.lookAt(camera.position);
  };

  // Event handlers (none for this card)
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
    // No GSAP timelines to kill
  };

  return group;
}
